const GEO_REFERENCE={west:59,east:78,south:20,north:39};
function geoMercator(lat){return Math.log(Math.tan(Math.PI/4+lat*Math.PI/360));}
function projectedVenue(lng,lat){
 const box=GEO_REFERENCE;
 return {x:100*(lng-box.west)/(box.east-box.west),
  y:100*(geoMercator(box.north)-geoMercator(lat))/(geoMercator(box.north)-geoMercator(box.south))};
}
const PHYSICAL_CITY_BOUNDS={Karachi:[24.6,25.3,66.6,67.5],Lahore:[31.1,31.8,74,74.7],Islamabad:[33.4,33.9,72.7,73.5]};
function isPhysicalVenue(item){
 const venue=String(item.venue||'').trim();
 if(!venue||/^(online|virtual|remote|tba|to be announced|unknown|n\/?a)$/i.test(venue)||/\b(virtual event|online only|webinar|zoom meeting|google meet|livestream)\b/i.test(venue))return false;
 if(item.online===true||item.is_online===true||item.location_verified===false)return false;
 const lat=item.latitude,lon=item.longitude;
 if(lat===null||lon===null||lat===undefined||lon===undefined||lat===''||lon==='')return false;
 const north=Number(lat),east=Number(lon),bounds=PHYSICAL_CITY_BOUNDS[item.city];
 if(!Number.isFinite(north)||!Number.isFinite(east)||!bounds)return false;
 if(north<bounds[0]||north>bounds[1]||east<bounds[2]||east>bounds[3])return false;
 // Never silently map a record to a generic city-centre placeholder.
 const city=CENTERS[item.city];
 if(Math.hypot((north-city.lat)*111000,(east-city.lng)*111000*Math.cos(north*Math.PI/180))<100)return false;
 return true;
}
function eventVenueGroups(events){
 const groups=new Map();
 for(const e of events){
  // Same venue with identical published lat/lon => ONE accurate pin, NEVER staggered pins.
  const key=[e.city,e.lat.toFixed(5),e.lng.toFixed(5)].join('|');
  if(!groups.has(key))groups.set(key,{id:'venue-'+key,city:e.city,venue:e.venue,lat:e.lat,lng:e.lng,
   ...projectedVenue(e.lng,e.lat),events:[]});
  if(!groups.get(key).events.some(x=>x.id===e.id))groups.get(key).events.push(e);
 }
 return [...groups.values()].sort((a,b)=>a.city.localeCompare(b.city)||a.venue.localeCompare(b.venue));
}
function venueGroups(){return eventVenueGroups(eligibleEvents());}

